"""Small, dependency-free guard for SQL generated by the model.

The data agent is intentionally read-only. This module normalizes model output
and rejects anything that is not a single read statement before it reaches the
database driver.
"""

from __future__ import annotations

import re


class SQLValidationError(ValueError):
    """Raised when generated SQL is empty, unsafe, or ambiguous."""


_READ_PREFIXES = ("SELECT", "WITH", "SHOW", "DESCRIBE", "DESC", "EXPLAIN")
_FORBIDDEN_WORDS = {
    "ALTER",
    "ATTACH",
    "CALL",
    "CREATE",
    "DELETE",
    "DROP",
    "GRANT",
    "INSERT",
    "LOAD",
    "RENAME",
    "REPLACE",
    "REVOKE",
    "TRUNCATE",
    "UPDATE",
}


def normalize_sql(sql: str) -> str:
    """Remove markdown wrappers and insignificant trailing whitespace."""

    if not isinstance(sql, str):
        raise SQLValidationError("SQL 必须是文本")
    normalized = sql.strip()
    normalized = re.sub(r"^```(?:sql)?\s*", "", normalized, flags=re.IGNORECASE)
    normalized = re.sub(r"\s*```$", "", normalized)
    return normalized.strip().rstrip(";").strip()


def _has_multiple_statements(sql: str) -> bool:
    in_single = False
    in_double = False
    escaped = False
    for char in sql:
        if escaped:
            escaped = False
            continue
        if char == "\\":
            escaped = True
            continue
        if char == "'" and not in_double:
            in_single = not in_single
        elif char == '"' and not in_single:
            in_double = not in_double
        elif char == ";" and not in_single and not in_double:
            return True
    return False


def validate_read_only_sql(sql: str) -> str:
    """Return normalized read-only SQL or raise ``SQLValidationError``."""

    normalized = normalize_sql(sql)
    if not normalized:
        raise SQLValidationError("SQL 不能为空")
    if _has_multiple_statements(normalized):
        raise SQLValidationError("只允许执行一条 SQL")

    upper_sql = normalized.upper()
    first_word = re.match(r"([A-Z]+)", upper_sql)
    if not first_word or first_word.group(1) not in _READ_PREFIXES:
        raise SQLValidationError("只允许执行查询语句")

    # A WITH query may contain an INSERT/UPDATE/DELETE body, so inspect all
    # statement keywords instead of trusting the first token alone.
    keywords = set(re.findall(r"\b[A-Z]+\b", upper_sql))
    forbidden = keywords & _FORBIDDEN_WORDS
    if forbidden:
        raise SQLValidationError(f"检测到禁止的 SQL 操作: {', '.join(sorted(forbidden))}")
    return normalized
